-- 자동 생성(2026-09 복구): 구글 드라이브 팀 원본 문서에서 파싱.
-- 재실행 안전(중복 검사 / ON CONFLICT).

-- stadiums: 10개 구단(잠실은 LG·두산 각각 1행). 프론트 stadiumMapper.ts 형식에 맞춤.

INSERT INTO stadiums (team_code, name, location, parking, subway, food, stadium_size, seat_count,
  features, ktx_info, taxi_info, bus_info, parking_tip, restaurants, tourism, accommodations,
  reservation_site, reservation_tip)
SELECT 'LG', '잠실야구장', '서울특별시 송파구 올림픽로 25, 잠실종합운동장 내', '잠실종합운동장 주차장 이용 가능', '2호선·9호선 종합운동장역 (종합운동장역에서 도보 이동 가능)', '잠실은 구장 내 먹거리 선택지가 많고, 외부 포장 음식과 함께 이용하는 관중도 많다. 특히 잠실은 김치말이국수, 삼겹살도시락, 치킨, 만두, 떡볶이, 고추튀김류가 직관 인기 메뉴로 자주 언급된다. 더운 날에는 김치말이국수가 시원하게 먹기 좋고, 식사 대용으로는 삼겹살도시락이 강하다. 또한 잠실은 맥주보이가 있어 좌석에서도 생맥주를 비교적 편하게 즐길 수 있다. 직접 매장까지 이동하지 않아도 관중석에서 생맥주를 구매할 수 있어, 경기 흐름을 놓치지 않고 먹거리와 응원을 즐기기 좋다.
인기 메뉴 후보: 김치말이국수, 삼겹살도시락, 우이락 고추튀김, 보영만두 군만두/쫄면, BHC 치킨, BBQ 치킨, 피자헛, 도미노피자, 죠스떡볶이, 명인만두, 통밥/덮밥류, KFC, 맘스터치, 브뤼셀프라이, 타코잇, 픽베이크, 생맥주, 맥주보이 좌석 판매 생맥주.
추천 조합: 잠실 대표 식사 메뉴=삼겹살도시락, 더운 날 시원하게=김치말이국수, 간단히 먹기=만두 + 떡볶이, 든든히 먹기=삼겹살도시락 + 치킨, 여럿이 나눠먹기=피자 + 치킨, 술안주 느낌=고추튀김 + 생맥주, 자리에서 편하게=맥주보이 생맥주.',
  '좌우 100m, 중앙 125m', '시설 기준 약 24,411석 / 운영 기준 약 23,750~25,000명', '서울 대표 야구장. LG와 두산이 공동 사용. 2026시즌 이후 잠실야구장 재개발 이슈 있음',
  '서울역 → 잠실야구장 약 40~50분', '서울역 → 잠실야구장 약 30~45분', NULL, '경기일에는 매우 혼잡. 주말, 라이벌전, 매진 경기에는 대중교통 추천', '잠실은 잠실새내 새마을시장 포장 코스가 가장 유명하다. 경기 전 포장해서 들어가기 좋다.
파오파오 - 새우만두, 고기만두 등 만두 포장으로 유명 / 깻잎닭강정 - 잠실새내 포장 인기 메뉴 / 고박사 - 경기 전후 식사하기 좋은 고깃집 후보 / 잠실새내 새마을시장 - 만두, 닭강정, 육회, 분식 등 포장 선택지 많음 / 방이먹자골목 - 경기 후 술집/식사 선택지 많음', '관광: 석촌호수, 롯데월드, 롯데월드타워, 올림픽공원. 경기 전 산책: 석촌호수, 올림픽공원. 경기 후 식사: 잠실새내, 방이먹자골목.',
  '잠실, 방이, 삼성/코엑스, 선릉, 강남', 'LG 트윈스 홈페이지/앱, 티켓링크', 'LG/두산 인기 경기는 오픈 직후 매진 가능성 높음. 주말, 어린이날, 라이벌전, 한화/KIA/롯데전은 예매 난이도 높음. 원정팬은 3루/원정응원석 위치 확인 필요.'
WHERE NOT EXISTS (SELECT 1 FROM stadiums WHERE team_code = 'LG');

