INSERT INTO stadiums (team_code, name, location, parking, subway, food, stadium_size, seat_count,
  features, ktx_info, taxi_info, bus_info, parking_tip, restaurants, tourism, accommodations,
  reservation_site, reservation_tip)
SELECT 'WO', '고척스카이돔', '서울특별시 구로구 경인로 430', '고척스카이돔 부설주차장 있음', '1호선 구일역 (구일역 2번 출구에서 도보 약 3분)', '고척은 돔구장이라 날씨 영향을 덜 받아 구장 안에서 음식을 먹기 편하다. 대표 메뉴는 크림새우다.
인기 메뉴 후보: 쉬림프쉐프 크림새우, 마라새우, 땅땅치킨, 올리브떡볶이, BK버거, 꼬치닭, 명랑핫도그, 스트릿츄러스, 마왕족발, 초장집, BBQ, 브뤼셀프라이, 우이락, 자담치킨.
추천 조합: 고척 처음 방문=크림새우, 매운맛 선호=마라새우, 든든히 먹기=버거 + 감자튀김, 여럿이 나눠먹기=족발 + 치킨, 간식=핫도그, 츄러스.',
  '좌우 99m, 중앙 122m', '약 16,000명', '국내 최초 돔구장. 비, 폭염, 미세먼지 영향이 적음',
  '서울역 → 구일역/고척돔 약 35~45분 / 광명역 → 고척돔 택시 약 30~40분', NULL, NULL, '경기/행사일에는 주차 제한 또는 매우 혼잡. 대중교통 추천', '고척은 구장 주변 선택지가 잠실처럼 넓지는 않지만, 포장 메뉴는 꽤 좋다.
백남옥손만두 - 고척돔 근처 포장 만두로 유명 / 더좋은축산 - 육회 포장 후보 / 오토김밥 고척점 - 김밥, 닭강정류 포장 후보 / 구일역/개봉역 주변 식당 - 분식, 고깃집, 샤브샤브 등 / 신도림/구로디지털단지 - 경기 전후 식사·술집 선택지 많음', '관광: 구로/신도림 상권, 영등포/문래까지 확장 가능. 산책: 안양천. 식사: 구일역, 개봉역, 신도림, 구로디지털단지.',
  '신도림, 구로, 영등포, 광명역 주변', '키움 히어로즈 홈페이지, NOL 티켓/인터파크 계열', '돔구장이라 우천취소 걱정이 거의 없음. 인기 원정팀 경기 예매 경쟁이 높음'
WHERE NOT EXISTS (SELECT 1 FROM stadiums WHERE team_code = 'WO');

INSERT INTO stadiums (team_code, name, location, parking, subway, food, stadium_size, seat_count,
  features, ktx_info, taxi_info, bus_info, parking_tip, restaurants, tourism, accommodations,
  reservation_site, reservation_tip)
SELECT 'SK', '인천 SSG 랜더스필드', '인천광역시 미추홀구 매소홀로 618, 문학경기장 단지', '문학경기장 주차장 이용 가능', '인천 1호선 문학경기장역 (문학경기장역에서 도보 이동 가능)', '랜더스필드는 크림새우 이미지가 강한 구장이지만, 2026년 기준으로는 컵물회, 우이락 고추튀김, 크림새우, 닭강정, 버거류, 빙수류까지 함께 묶어 안내하는 것이 좋다. 특히 컵물회는 더운 날 야구장에서 먹기 좋은 시원한 메뉴이고, 우이락 고추튀김은 맥주 안주로 잘 어울린다.
인기 메뉴 후보: 컵물회, 우이락 고추튀김, 스테이션 크림새우, 마라새우, 허갈 닭강정, 버거원더스 치즈푸틴, 88스테이크버거, 랜더스 버거류, 커빙 빙수, 치킨류, 떡볶이/분식류, 카페/디저트류.
추천 조합: 랜더스필드 대표 메뉴=크림새우, 더운 날 시원하게=컵물회, 맥주 안주=우이락 고추튀김, 여럿이 나눠먹기=닭강정 + 감자튀김, 든든히 먹기=버거 + 치즈푸틴, 더운 날 디저트=커빙 빙수, 술안주 조합=크림새우 + 고추튀김.',
  '좌우 95m, 중앙 120m', '약 23,000명', '인천 대표 야구장. 문학경기장 단지 내 위치',
  '광명역 → 랜더스필드 택시 약 40~60분 / 서울역 → 랜더스필드 대중교통 약 70~90분', NULL, NULL, '경기일 선불제 운영 가능. 인기 경기에는 매우 혼잡', '문학경기장 바로 앞보다 구월동/인천터미널/예술회관역 상권으로 이동하는 편이 선택지가 많다.
구월동 로데오 - 경기 후 술집, 고깃집, 식사 선택지 많음 / 인천터미널 상권 - 식당, 카페, 쇼핑몰 접근 좋음 / 예술회관역 주변 - 밥집, 술집 많음 / 성탄상황곱창 - 곱창류 후보 / 통큰가마솥양평해장순대국 - 경기 후 해장/식사 후보', '관광: 차이나타운, 송월동 동화마을, 송도 센트럴파크. 경기 전후 식사: 구월동, 인천터미널, 예술회관역. 시장/먹거리: 신기시장, 구월동 상권.',
  '구월동, 인천터미널, 송도, 주안', 'SSG 공식 앱, ticket.ssg.com, SSG.com', '인기 매치업은 응원석/테이블석 선점이 중요. 원정팬은 3루쪽 위치 확인 필요'
WHERE NOT EXISTS (SELECT 1 FROM stadiums WHERE team_code = 'SK');

